import { normalizeStudioProvider } from '@cossackframework/studio';

if (normalizeStudioProvider(' PostgreSQL ') !== 'postgres') {
  throw new Error('Provider aliases should normalize before selecting a connection');
}
if (normalizeStudioProvider('d1') !== 'd1-local') {
  throw new Error('The local D1 provider alias should remain explicit');
}
if (normalizeStudioProvider('unknown-driver') !== undefined) {
  throw new Error('Unknown providers must not be guessed');
}

import { createServer } from 'node:http';
import { runStudio, type StudioConnection } from '@cossackframework/studio';

async function availablePort(): Promise<number> {
  const server = createServer();
  await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('No loopback port was allocated');
  await new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  return address.port;
}
const controller = new AbortController();
let closed = false;
let ready = false;
const connection: StudioConnection = {
  info: { provider: 'sqlite', label: 'offline fixture', remote: false },
  async execute() { return { rows: [], affectedRows: 0, durationMs: 0 }; },
  async close() { closed = true; },
};
await runStudio({ connection, port: await availablePort(), quiet: true, open: false,
  signal: controller.signal, onReady(info) {
    if (info.remote || !info.origin.startsWith('http://127.0.0.1:')) throw new Error('Expected loopback readiness');
    ready = true;
    controller.abort();
  },
});
if (!ready || !closed) throw new Error('Studio must report readiness and close its connection on abort');
